{
  "name": "EPICS 过程变量记录器",
  "name_en": "EPICS Process Variable Logger",
  "manufacturer": "",
  "description": "用于实验控制系统的非物理软件组件，负责连接并监测 EPICS 过程变量（PV），按配置创建日志目录、持续采集数据、处理新增监测请求，并在收到停止信号后结束记录。",
  "description_en": "A non-physical software component for laboratory control systems that connects to and monitors EPICS process variables (PVs), creates logging folders from configuration, continuously collects data, handles requests for newly monitored PVs, and stops logging when an exit signal is received.",
  "actions": [
    {
      "action_name": "auto-read_configfile",
      "description": "读取记录配置文件，确定监测的 PV、日志路径以及采集起止时间等设置。",
      "description_en": "Read the logging configuration file to determine monitored PVs, log paths, and collection start and end times."
    },
    {
      "action_name": "auto-make_pvlog_folder",
      "description": "创建 PV 日志文件夹，并按需要切换到该目录以保存记录数据和元数据。",
      "description_en": "Create the PV log folder and optionally change into that directory to store logged data and metadata."
    },
    {
      "action_name": "auto-connect_pvs",
      "description": "连接或重新连接配置中的 PV，并建立相应的监测对象与元数据文件。",
      "description_en": "Connect or reconnect the configured PVs and create the corresponding monitored objects and metadata files."
    },
    {
      "action_name": "auto-add_pv",
      "description": "将新的 PV 加入记录列表，可同时附加描述和变更阈值等信息。",
      "description_en": "Add a new PV to the logging list, optionally with description and monitor deadband information."
    },
    {
      "action_name": "auto-look_for_new_pvs",
      "description": "检查新增 PV 请求文件，并将其中列出的 PV 动态加入监测过程。",
      "description_en": "Check for a new-PV request file and dynamically add the listed PVs to the monitoring process."
    },
    {
      "action_name": "auto-look_for_exit_signal",
      "description": "检查停止信号，例如停止文件或到达结束时间，以决定是否终止数据采集。",
      "description_en": "Check for an exit signal, such as a stop file or the configured end time, to decide whether data collection should stop."
    },
    {
      "action_name": "auto-finish",
      "description": "结束数据记录流程并完成收尾处理。",
      "description_en": "Finish the data logging process and perform final cleanup."
    },
    {
      "action_name": "auto-on_exit",
      "description": "在退出时执行收尾操作，确保记录过程正确结束。",
      "description_en": "Perform exit-time cleanup actions to ensure the logging process ends properly."
    },
    {
      "action_name": "auto-run",
      "description": "启动并运行 PV 记录主循环，在开始时间后持续采集数据，直到收到退出条件为止。",
      "description_en": "Start and run the main PV logging loop, collecting data after the start time until an exit condition is reached."
    }
  ],
  "tag_hints": [
    "EPICS PV logging",
    "process variable monitoring",
    "time-series data collection",
    "experiment data logging",
    "configuration-based acquisition",
    "dynamic PV enrollment",
    "stop-signal controlled logging"
  ]
}

